import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';
import test from 'node:test';
import { distDir, distExists, decode, listHtmlFiles } from './support/dist.mjs';
import { pageOg, slugFor } from '../src/data/og.ts';
import { scenes, ogSceneFor } from '../src/data/scenes.mjs';

// Share cards are generated by the build from src/data/og.ts, in the Ouro
// brand: nobody draws or uploads them by hand (Ari, 2026-10-15). Since the
// storybook world (2026-11-06) each one sets its title over its page's scene.

const meta = (html, attr, name) => {
  const m = html.match(new RegExp(`<meta ${attr}="${name}" content="([^"]*)"`));
  return m ? decode(m[1]) : undefined;
};

test('every share card names a mark that exists', () => {
  for (const [route, entry] of Object.entries(pageOg)) {
    const mark = entry.mark ?? 'ouro';
    assert.ok(fs.existsSync(path.join('src/og/marks', `${mark}.png`)), `${route}: missing mark ${mark}`);
  }
});

// The width and height from a JPEG's start-of-frame marker.
const jpegSize = (bytes) => {
  for (let i = 2; i < bytes.length;) {
    const marker = bytes[i + 1];
    if (marker >= 0xc0 && marker <= 0xc3) return [bytes.readUInt16BE(i + 7), bytes.readUInt16BE(i + 5)];
    i += 2 + bytes.readUInt16BE(i + 2);
  }
  return null;
};

test('every share card is set in a storybook scene the site serves', () => {
  for (const route of Object.keys(pageOg)) {
    const scene = ogSceneFor(route);
    assert.ok(scene in scenes, `${route}: unknown scene ${scene}`);
    assert.ok(distExists(`brand/storybook/og/${scene}.jpg`), `${route}: og scene ${scene} is not served`);
  }
});

test('the build generates a 1200x630 JPEG card for every manifest entry, small enough for any feed', () => {
  for (const route of Object.keys(pageOg)) {
    const file = `og/${slugFor(route)}.jpg`;
    assert.ok(distExists(file), `${route}: ${file} was not generated`);
    const jpg = fs.readFileSync(path.join(distDir, file));
    assert.equal(jpg.readUInt16BE(0), 0xffd8, `${file} is a JPEG`);
    assert.deepEqual(jpegSize(jpg), [1200, 630], `${file} size`);
    assert.ok(jpg.length < 400_000, `${file} is ${jpg.length} bytes`);
  }
});

test('every page advertises an existing card with its size and alt text', () => {
  for (const file of listHtmlFiles()) {
    const html = fs.readFileSync(file, 'utf8');
    const image = meta(html, 'property', 'og:image');
    if (!image) continue;
    const page = path.relative(distDir, file);
    assert.ok(distExists(new URL(image).pathname), `${page}: ${image} is not in the build`);
    assert.equal(meta(html, 'name', 'twitter:image'), image, `${page}: twitter:image`);
    assert.equal(meta(html, 'property', 'og:image:width'), '1200', `${page}: og:image:width`);
    assert.equal(meta(html, 'property', 'og:image:height'), '630', `${page}: og:image:height`);
    const alt = meta(html, 'property', 'og:image:alt');
    assert.ok(alt && alt.length > 10, `${page}: og:image:alt`);
    assert.equal(meta(html, 'name', 'twitter:image:alt'), alt, `${page}: twitter:image:alt`);
    assert.equal(meta(html, 'property', 'og:site_name'), 'Ouro', `${page}: og:site_name`);
  }
});

test('the homepage card says what the card shows', () => {
  const html = fs.readFileSync(path.join(distDir, 'index.html'), 'utf8');
  const entry = pageOg['/'];
  assert.equal(meta(html, 'property', 'og:image:alt'), `${entry.title} ${scenes.ourostack}`);
});

// One type scale on every card (taste review r5, 2026-11-06): the title is set
// at a single size and only its line count changes, and a zone too small for it
// fails the build instead of shrinking the words.
test('every share card sets its title at the one title size', () => {
  const src = fs.readFileSync('src/pages/og/[...slug].jpg.ts', 'utf8');
  assert.match(src, /export const TITLE_SIZE = \d+/);
  assert.match(src, /const titleSize = TITLE_SIZE\n/);
  assert.match(src, /if \(!lines\) throw new Error/);
});

// The Butler card (flagged in taste reviews r7, r12 and r13): its cottage roof
// runs to the top of the art, so there is no sky to set a title in, and every
// sky made from the top rows washed the roof pink. Ari's ruling (r14): a
// storybook title plate. A clean, solid plate in the light theme's page colour
// across the top, a thin gold rule along its lower edge, and the canonical
// scene below it at full strength, with no gradient, wash or made-up sky.
// The look is checked by eye next to three other cards.
test('the Butler card stands its title on a solid cream plate over the whole scene', async () => {
  const { default: sharp } = await import('sharp');
  const { PLATE, plateFrame, W, H } = await import('../src/og/frames.mjs');
  const file = path.join(distDir, 'og/og-butler.jpg');
  assert.ok(fs.existsSync(file), 'og-butler.jpg was not built');
  const { data, info } = await sharp(file).removeAlpha().raw().toBuffer({ resolveWithObject: true });
  assert.deepEqual([info.width, info.height], [W, H]);
  const header = 'public/brand/storybook/headers/butler.webp';
  const { plateH } = await plateFrame(header);
  // The whole header at card width fills the card under the plate.
  assert.equal(plateH, H - Math.round((576 * W) / 1536));
  const px = (x, y) => { const i = (y * info.width + x) * 3; return [data[i], data[i + 1], data[i + 2]]; };
  const hex = (h) => [1, 3, 5].map((i) => parseInt(h.slice(i, i + 2), 16));
  const near = (a, b, tol) => a.every((v, i) => Math.abs(v - b[i]) <= tol);
  // Solid paper wherever the words are not: the plate's margins and the band
  // under the title, every pixel within JPEG noise of the page colour.
  const paper = hex(PLATE.paper);
  const blank = [];
  for (let y = 2; y < plateH - PLATE.rule - 4; y++) for (const x of [2, 6, W - 7, W - 3]) blank.push([x, y]);
  for (let x = 2; x < W - 2; x += 3) for (const y of [3, plateH - PLATE.rule - 6]) blank.push([x, y]);
  for (const [x, y] of blank) assert.ok(near(px(x, y), paper, 6), `plate at ${x},${y} is ${px(x, y)}, not the page colour`);
  // The gold rule runs the full width along the plate's lower edge.
  const gold = hex(PLATE.gold);
  for (let x = 4; x < W - 4; x += 7) assert.ok(near(px(x, plateH - PLATE.rule + 1), gold, 18), `no gold rule at x=${x}`);
  // Under the plate, the scene at full strength: the canonical header resized,
  // not washed or faded (mean difference within JPEG noise).
  const scene = await sharp(header).resize({ width: W }).removeAlpha().raw().toBuffer();
  let diff = 0;
  let n = 0;
  for (let y = 0; y < H - plateH; y += 3) for (let x = 0; x < W; x += 3) {
    for (let c = 0; c < 3; c++) diff += Math.abs(scene[(y * W + x) * 3 + c] - data[((y + plateH) * W + x) * 3 + c]);
    n += 3;
  }
  assert.ok(diff / n < 6, `the scene under the plate differs from the canonical art by ${(diff / n).toFixed(1)} levels`);
  // The title on the plate is far past AA (ink on the page colour).
  const lin = (v) => { v /= 255; return v <= 0.04045 ? v / 12.92 : ((v + 0.055) / 1.055) ** 2.4; };
  const lum = ([r, g, b]) => 0.2126 * lin(r) + 0.7152 * lin(g) + 0.0722 * lin(b);
  assert.ok((lum(paper) + 0.05) / (lum([0x1a, 0x21, 0x18]) + 0.05) >= 7);
});

// No share card lays anything over its art (Ari, 2026-11-08: no picture fades
// to nothing): no scrim, no wash, no made-up sky the art melts into. A card
// shows its scene's own crop, or stands its title on the solid plate.
test('no share card fades or washes its art', () => {
  const src = fs.readFileSync('src/pages/og/[...slug].jpg.ts', 'utf8');
  const frames = fs.readFileSync('src/og/frames.mjs', 'utf8');
  for (const [name, text] of [['[...slug].jpg.ts', src], ['frames.mjs', frames]]) {
    assert.doesNotMatch(text, /<(?:linear|radial)Gradient\b|stop-opacity|dest-in|skyFrame|scrimSvg/, name);
  }
  assert.match(src, /\.composite\(\[\{ input: Buffer\.from\(wordsLayer\) \}\]\)/);
  const plates = [...src.matchAll(/'?([a-z-]+)'?: \{ file: 'headers\/[a-z-]+\.webp', plate: true \}/g)].map((m) => m[1]);
  assert.ok(plates.length >= 8, `found plate scenes: ${plates}`);
});

// The plate cards' titles read at AA on the plate.
test('titles on plate cards read at AA', async () => {
  const { default: sharp } = await import('sharp');
  const lin = (v) => { v /= 255; return v <= 0.04045 ? v / 12.92 : ((v + 0.055) / 1.055) ** 2.4; };
  const ink = 0.2126 * lin(0x1a) + 0.7152 * lin(0x21) + 0.0722 * lin(0x18);
  const plateCards = ['lab-docs-tasks-and-work', 'blog-trust-the-agent', 'lab-model-reviews-minimax', 'lab-what-is-an-agent-harness', 'lab-docs-architecture'];
  for (const slug of plateCards) {
    const { data, info } = await sharp(path.join(distDir, `og/og-${slug}.jpg`)).removeAlpha().raw().toBuffer({ resolveWithObject: true });
    for (let x0 = 16; x0 < 1100; x0 += 100) {
      const ls = [];
      for (let y = 16; y < 130; y++) for (let x = x0; x < x0 + 100; x++) { const i = (y * info.width + x) * 3; ls.push(0.2126 * lin(data[i]) + 0.7152 * lin(data[i + 1]) + 0.0722 * lin(data[i + 2])); }
      ls.sort((a, b) => a - b);
      const ratio = (ls[ls.length >> 1] + 0.05) / (ink + 0.05);
      assert.ok(ratio >= 4.5, `${slug}: the ground behind the title at x=${x0} gives ${ratio.toFixed(2)}:1, under AA`);
    }
  }
});
